# Apply Edit B (orthogonalize loop direction d24 out of upper-layer writers) on top of snapshot
import numpy as np, torch, os, shutil, glob
d = {int(k):v for k,v in np.load('/work/loop_dirs.npz').items()}
ds = torch.from_numpy(d[24]).float()
ds = ds / ds.norm()
ALPHA = 1.0
LAYERS = range(15, 24)
snap = '/work/edit_A'
# start from Edit A snapshot
for f in glob.glob('/work/edited/*'): os.remove(f)
for f in glob.glob(snap + '/*'): shutil.copy(f, '/work/edited/')
def getW(name):
    fn = '/work/edited/' + name + '.safetensors'
    if os.path.exists(fn): return load(name).clone()  # load returns current edit
    return load_original(name).clone()
for L in LAYERS:
    names = [f'model.language_model.layers.{L}.mlp.down_proj.weight']
    if L in (3,7,11,15,19,23): names.append(f'model.language_model.layers.{L}.self_attn.o_proj.weight')
    else: names.append(f'model.language_model.layers.{L}.linear_attn.out_proj.weight')
    for name in names:
        W = getW(name)
        proj = torch.outer(ds, ds @ W)  # [hidden, fan]
        W2 = W - ALPHA * proj
        save_edit(name, W2)
print('done; edited tensors:', os.listdir('/work/edited'))

